  "the-legend-of-zelda-breath-of-the-wild": {"summary":"The Legend of Zelda: Breath of the Wild is the first 3D open-world game in the Zelda series. Link can travel anywhere and be equipped with weapons and armor found throughout the world to grant him various bonuses. Unlike many games in the series, Breath of the Wild does not impose a specific order in which quests or dungeons must be completed. While the game still has environmental obstacles such as weather effects, inhospitable lands, or powerful enemies, many of them can be overcome using the right method. A lot of critics ranked Breath of the Wild as one of the best video games of all time.","themes":["Action","Fantasy","Science fiction","Sandbox","Open world"],"gameModes":["Single player"],"availability":["Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/games/detail/the-legend-of-zelda-breath-of-the-wild-switch/"}],"media":["sckj69","sckj6a","sckj6d","sckj6f","sckj6h","sckj6b"],"trailer":{"id":"zw47_q9wbBE","name":"Trailer"},"releaseDates":[{"platform":"Switch","date":"Mar 03, 2017"}],"multiplayer":null,"engines":["In-house engine","Havok Physics"],"perspectives":["Third person"],"similar":["god-of-war--1","horizon-zero-dawn","the-witcher-3-wild-hunt","red-dead-redemption-2","super-mario-odyssey"],"xbox":null,"nintendo":{"nsuid":"70010000000025","url":"https://www.nintendo.com/games/detail/the-legend-of-zelda-breath-of-the-wild-switch/","price":59.99,"regularPrice":59.99,"discounted":false,"currency":"USD","sizeGb":14.5,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition","ROM Bundle","Physical Edition - US"]},"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
