  "sekiro-shadows-die-twice": {"summary":"Sekiro: Shadows Die Twice is an action-adventure game set in a reimagined late 1500s Sengoku-era Japan. Players control Wolf, a shinobi on a mission to rescue his kidnapped lord and seek revenge on his enemies. The game emphasizes precise sword combat, stealth, and mobility, replacing traditional RPG elements with a posture-based dueling system.","themes":["Action","Fantasy","Historical","Stealth"],"gameModes":["Single player"],"availability":["PS4","PC","Xbox One"],"stores":[{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/232898"},{"label":"Steam","url":"https://store.steampowered.com/app/814380"}],"media":["sn1rmqcvrwomyuttaoyq","ocxemodvr6oa72argpyo","tjxbj2hryec06ahdi2ep","sk8lqukaqalhq2mrzkqd","jo1pi5md3myj0pxynz9p","ozcogbafdzztevnidcvt"],"trailer":{"id":"gV010Rgu_2M","name":"Gameplay video"},"releaseDates":[{"platform":"Xbox One","date":"Mar 22, 2019"},{"platform":"PC","date":"Mar 22, 2019"},{"platform":"PS4","date":"Mar 22, 2019"}],"multiplayer":null,"engines":[],"perspectives":["Third person"],"similar":["the-last-of-us-part-ii","god-of-war--1","a-plague-tale-innocence","borderlands-3"],"xbox":null,"nintendo":null,"playstation":{"productId":"UP0002-CUSA12047_00-SEKIROGAME000001","conceptId":"232898","url":"https://store.playstation.com/en-us/concept/232898","price":59.99,"regularPrice":59.99,"discounted":false,"currency":"USD","plusIncluded":false,"editions":[],"sizeGb":null},"steam":{"appId":"814380","url":"https://store.steampowered.com/app/814380","price":59.99,"regularPrice":59.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
