  "pokemon-violet": {"summary":"Catch, battle, and train Pokémon in the Paldea Region, a vast land filled with lakes, towering peaks, wastelands, small towns, and sprawling cities. Explore a wide-open world at your own pace and traverse land, water, and air by riding on a form-shifting Legendary Pokémon. Choose either Sprigatito, Fuecoco, or Quaxly, to be your first partner Pokémon before setting off on your journey through Paldea.","themes":["Action","Fantasy","Kids","Open world"],"gameModes":["Single player","Multiplayer"],"availability":["Switch 2","Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/store/products/pokemon-violet-switch/"}],"media":["scfv7v","scfv7w","scfv7x","scfv7y","ar3vl4"],"trailer":{"id":"MAmueMsFR1o","name":"Announcement Trailer"},"releaseDates":[{"platform":"Switch","date":"Nov 18, 2022"},{"platform":"Switch 2","date":"Jun 05, 2025"}],"multiplayer":null,"engines":[],"perspectives":["Third person"],"similar":["borderlands-3"],"xbox":null,"nintendo":{"nsuid":"70010000053971","url":"https://www.nintendo.com/store/products/pokemon-violet-switch/","price":59.99,"regularPrice":59.99,"discounted":false,"currency":"USD","sizeGb":10.1,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition","ROM Bundle","Physical Edition - US","Physical Edition + DLC - US"]},"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
