  "batman-arkham-city": {"summary":"Batman: Arkham City builds upon the intense, atmospheric foundation of Batman: Arkham Asylum, sending players soaring into Arkham City, the new maximum security \"home\" for all of Gotham City's thugs, gangsters and insane criminal masterminds. Set inside the heavily fortified walls of a sprawling district in the heart of Gotham City, this highly anticipated sequel introduces a brand-new story that draws together a new all-star cast of classic characters and murderous villains from the Batman universe, as well as a vast range of new and enhanced gameplay features to deliver the ultimate…","themes":["Action","Stealth","Open world"],"gameModes":["Single player"],"availability":["PC","Switch"],"stores":[{"label":"Epic Games","url":"https://store.epicgames.com/en-US/p/batman-arkham-city"},{"label":"Nintendo eShop","url":"https://www.nintendo.com/store/products/batman-arkham-city-switch/"},{"label":"Steam","url":"https://store.steampowered.com/app/57400"}],"media":["optmyqz2utbniy4abipu","ygltnojhp2e8dvo8yapm","zogoamnedpsulpqblwfn","ephvdh5mjs2jdadxzw4u","mpgh7k42h4gpg9saizpr","scu5ku"],"trailer":{"id":"FCTdm8Nb7Ps","name":"Trailer"},"releaseDates":[{"platform":"PC","date":"Nov 22, 2011"},{"platform":"Switch","date":"Dec 01, 2023"}],"multiplayer":null,"engines":["Unreal Engine 3"],"perspectives":["Third person"],"similar":["batman-arkham-asylum","batman-arkham-knight"],"xbox":null,"nintendo":{"nsuid":"70010000045911","url":"https://www.nintendo.com/store/products/batman-arkham-city-switch/","price":9.99,"regularPrice":24.99,"discounted":true,"currency":"USD","sizeGb":12.4,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition"]},"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
