  "returnal": {"summary":"Returnal is a 2021 roguelike third-person shooter video game developed by Housemarque and published by Sony Interactive Entertainment. It follows Selene Vassos, an astronaut who lands on the planet Atropos in search of the mysterious \"White Shadow\" signal and finds herself trapped in a time loop. After crash-landing on a shape-shifting alien planet, Selene finds herself fighting tooth and nail for survival. Every time she’s defeated, the player is forced to restart the journey.","themes":["Action","Science fiction","Horror"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["PC","PS5"],"stores":[{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/10000176"},{"label":"Epic Games","url":"https://store.epicgames.com/p/returnal"},{"label":"Steam","url":"https://store.steampowered.com/app/1649240/Returnal"}],"media":["sc8bj6","sc8bj8","sc8bja","sc8bj9","sc8bj7","ar7fb"],"trailer":{"id":"5929rKazHbE","name":"Gameplay Trailer"},"releaseDates":[{"platform":"PS5","date":"Apr 30, 2021"},{"platform":"PC","date":"Feb 15, 2023"}],"multiplayer":{"onlineMax":2,"onlineCoopMax":2,"offlineCoopMax":null,"splitscreen":false,"campaignCoop":true},"engines":["Unreal Engine 4"],"perspectives":["First person","Third person"],"similar":["control","doom-eternal","dead-cells","tunic","god-of-war--1"],"xbox":null,"nintendo":null,"playstation":{"productId":"UP9000-PPSA01284_00-RETURNALGAME0001","conceptId":"10000176","url":"https://store.playstation.com/en-us/concept/10000176","price":69.99,"regularPrice":69.99,"discounted":false,"currency":"USD","plusIncluded":true,"editions":[],"sizeGb":null},"steam":{"appId":"1649240","url":"https://store.steampowered.com/app/1649240","price":59.99,"regularPrice":59.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
