  "the-legend-of-zelda-echoes-of-wisdom": {"summary":"The people of Hyrule are being stolen away by strange rifts that have appeared, and with a certain swordsman among those missing, it’s up to Princess Zelda to save her kingdom. Team up with the mysterious fairy, Tri, and use the power of the Tri Rod to learn how to create echoes, imitations of things found in the environment. You can then recreate those echoes whenever you like to solve puzzles and defeat enemies. Create echoes like water blocks to reach new heights, make bridges out of old beds, throw rocks at foes, or find your own creative combination of echoes to do things your way. You…","themes":["Action","Fantasy"],"gameModes":["Single player"],"availability":["Switch 2","Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/us/store/products/the-legend-of-zelda-echoes-of-wisdom-switch/"}],"media":["scsso6","scsso7","scssob","scsso8","scssoa","scsso9"],"trailer":{"id":"Sh0l78KD7mA","name":"Trailer"},"releaseDates":[{"platform":"Switch","date":"Sep 26, 2024"},{"platform":"Switch 2","date":"Jun 05, 2025"}],"multiplayer":null,"engines":[],"perspectives":["Bird view / Isometric","Side view"],"similar":["borderlands-3"],"xbox":null,"nintendo":{"nsuid":"70010000084618","url":"https://www.nintendo.com/us/store/products/the-legend-of-zelda-echoes-of-wisdom-switch/","price":59.99,"regularPrice":59.99,"discounted":false,"currency":"USD","sizeGb":5.7,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition","Physical Edition - US"]},"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
