  "stellar-blade": {"summary":"Stellar Blade is a third-person action-adventure game set on a post-apocalyptic Earth. Players control Eve, an elite soldier deployed from an orbital colony to reclaim the planet from hostile creatures called Naytibas. The combat system emphasizes timing-based parrying and evasion, with skill gauges that unlock powerful attacks and buffs. The game features exploration across ruined environments, side quests from NPC survivors in the last human city of Xion, and a narrative with multiple endings based on player choices.","themes":["Action","Science fiction"],"gameModes":["Single player"],"availability":["Switch 2","PC","PS5"],"stores":[{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/10006891"},{"label":"Epic Games","url":"https://store.epicgames.com/en-US/p/stellar-blade-fa21c3"},{"label":"Steam","url":"https://store.steampowered.com/app/3489700/Stellar_Blade/"}],"media":["scumka","scumkb","sc6dq4","scix66","sc6dq5","scumkc"],"trailer":{"id":"vLsSuuSAIys","name":"Teaser"},"releaseDates":[{"platform":"PS5","date":"Apr 26, 2024"},{"platform":"PC","date":"Jun 11, 2025"},{"platform":"Switch 2","date":"TBD"}],"multiplayer":null,"engines":["Unreal Engine 4"],"perspectives":["Third person"],"similar":["cyberpunk-2077"],"xbox":null,"nintendo":null,"playstation":{"productId":"UP9000-PPSA13196_00-STELLARBLADE0000","conceptId":"10006891","url":"https://store.playstation.com/en-us/concept/10006891","price":69.99,"regularPrice":69.99,"discounted":false,"currency":"USD","plusIncluded":true,"editions":[],"sizeGb":null},"steam":{"appId":"3489700","url":"https://store.steampowered.com/app/3489700","price":59.99,"regularPrice":59.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
