  "metroid-prime-4-beyond": {"summary":"Deadly sharpshooter Sylux has finally caught up with renowned bounty hunter Samus Aran! After an unexpected accident in the wake of their clash, Samus finds herself transported to Viewros— a mysterious planet once inhabited by an ancient race. Now she must explore this planet, all while battling the strange creatures that inhabit it, to find her way home. Scan your surroundings for clues, make the most of your equipment and weapons, and use Samus's newfound psychic abilities— and her technologically advanced bike, the Vi-O-La— to traverse and explore the environment. Operate mechanisms,…","themes":["Action","Science fiction"],"gameModes":["Single player"],"availability":["Switch 2","Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/us/store/products/metroid-prime-4-beyond-switch/"}],"media":["scssmm","scssmk","scssml","scssmn","scssmo","sctr39"],"trailer":{"id":"mMAgmdR8jwU","name":"Announcement Trailer"},"releaseDates":[{"platform":"Switch","date":"Dec 04, 2025"},{"platform":"Switch 2","date":"Dec 04, 2025"}],"multiplayer":null,"engines":[],"perspectives":["First person"],"similar":["gears-5"],"xbox":null,"nintendo":{"nsuid":"70010000084766","url":"https://www.nintendo.com/us/store/products/metroid-prime-4-beyond-switch/","price":59.99,"regularPrice":59.99,"discounted":false,"currency":"USD","sizeGb":27.7,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition","Physical Edition - US"]},"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
